// Regenerates one Code Connect template per Lemonade asset, per platform.
//
//   node scripts/generate-asset-templates.mjs                  # everything
//   node scripts/generate-asset-templates.mjs icons            # one asset type
//   node scripts/generate-asset-templates.mjs flags swiftui    # one of each
//
// Assets are icons and country flags. Both are enums in code, generated by
// svg-asset-converter.main.kts, and both are plain property-less components in
// Figma — so their mappings are generated here rather than written by hand.
//
// Every platform must be generated and published. Figma resolves a nested asset
// by node, and when a label has no template for that node it falls back to
// another label's — so a missing SwiftUI icon does not render as a blank, it
// renders the Kotlin snippet inside a Swift call.

import { readFileSync, writeFileSync, mkdirSync, rmSync, readdirSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const here = dirname(fileURLToPath(import.meta.url))
const root = join(here, '..')
const repo = join(root, '..')

const pascal = (name) =>
  name
    .split(/[-_ ]+/)
    .filter(Boolean)
    .map((part) => part[0].toUpperCase() + part.slice(1))
    .join('')

// Kotlin enum entries carry no raw value, so the member name is derived from the
// kebab-case Figma name. Swift cases carry the Figma name as their raw value, so
// the mapping is read straight off the enum instead of being re-derived.
const kotlinMembers = (src) =>
  new Map([...src.matchAll(/^\s+([A-Z][A-Za-z0-9]*)[,(]/gm)].map((m) => [pascal(m[1]), m[1]]))
const swiftMembers = (src) =>
  new Map([...src.matchAll(/^\s+case ([A-Za-z][A-Za-z0-9]*) = "([^"]+)"/gm)].map((m) => [m[2], m[1]]))

// Some assets have more Figma components than enum entries. Brand logos ship a
// -dark counterpart per brand, but the component resolves the dark artwork from
// the theme, so both nodes reference the same enum entry.
const stripDark = (name) => name.replace(/-dark$/, '')

const PLATFORMS = {
  compose: { dir: 'connect', tag: 'kotlin' },
  swiftui: { dir: 'connect-swiftui', tag: 'swift' },
}

const ASSETS = {
  icons: {
    manifest: 'icons.manifest.json',
    entries: 'icons',
    urlToken: '<LEMONADE_ICONS>',
    outSub: 'icons',
    normalise: (name) => name,
    compose: {
      enumPath: 'kmp/core/src/commonMain/kotlin/com/teya/lemonade/core/LemonadeIcons.kt',
      members: kotlinMembers,
      keyFor: (name) => pascal(name),
      reference: (m) => `LemonadeIcons.${m}`,
      imports: ['import com.teya.lemonade.core.LemonadeIcons'],
    },
    swiftui: {
      enumPath: 'swiftui/Sources/Lemonade/LemonadeIcons.swift',
      members: swiftMembers,
      keyFor: (name) => name,
      reference: (m) => `LemonadeIcon.${m}`,
      imports: [],
    },
  },
  flags: {
    manifest: 'flags.manifest.json',
    entries: 'flags',
    urlToken: '<LEMONADE_FLAGS>',
    outSub: 'flags',
    normalise: (name) => name,
    compose: {
      enumPath: 'kmp/core/src/commonMain/kotlin/com/teya/lemonade/core/LemonadeCountryFlags.kt',
      members: kotlinMembers,
      keyFor: (name) => pascal(name),
      reference: (m) => `LemonadeCountryFlags.${m}`,
      imports: ['import com.teya.lemonade.core.LemonadeCountryFlags'],
    },
    swiftui: {
      enumPath: 'swiftui/Sources/Lemonade/LemonadeCountryFlags.swift',
      members: swiftMembers,
      keyFor: (name) => name,
      reference: (m) => `LemonadeCountryFlag.${m}`,
      imports: [],
    },
  },
  brandLogos: {
    manifest: 'brand-logos.manifest.json',
    entries: 'brandLogos',
    urlToken: '<LEMONADE_COMPONENTS>',
    outSub: 'brand-logos',
    normalise: stripDark,
    compose: {
      enumPath: 'kmp/core/src/commonMain/kotlin/com/teya/lemonade/core/LemonadeBrandLogos.kt',
      members: kotlinMembers,
      keyFor: (name) => pascal(name),
      reference: (m) => `LemonadeBrandLogos.${m}`,
      imports: ['import com.teya.lemonade.core.LemonadeBrandLogos'],
    },
    swiftui: {
      enumPath: 'swiftui/Sources/Lemonade/LemonadeBrandLogos.swift',
      members: swiftMembers,
      keyFor: (name) => name,
      reference: (m) => `LemonadeBrandLogo.${m}`,
      imports: [],
    },
  },
}

const args = process.argv.slice(2)
const assetNames = args.filter((a) => a in ASSETS)
const platformNames = args.filter((a) => a in PLATFORMS)
const unknown = args.filter((a) => !(a in ASSETS) && !(a in PLATFORMS))
if (unknown.length) {
  console.error(`Unknown argument(s): ${unknown.join(', ')}`)
  console.error(`Assets: ${Object.keys(ASSETS).join(', ')}   Platforms: ${Object.keys(PLATFORMS).join(', ')}`)
  process.exit(1)
}
const assets = assetNames.length ? assetNames : Object.keys(ASSETS)
const platforms = platformNames.length ? platformNames : Object.keys(PLATFORMS)

let failed = false

for (const assetName of assets) {
  const asset = ASSETS[assetName]
  const manifest = JSON.parse(readFileSync(join(root, asset.manifest), 'utf8'))
  const items = manifest[asset.entries]
  // Entries the code enum has but Figma does not. Recorded in the manifest so
  // the gap is visible and reviewable rather than silently tolerated. Stored as
  // Figma names, so each platform maps them into its own key space below.
  const knownUnmapped = manifest.knownUnmapped ?? []
  // Enum entries served by another entry's component rather than one of their
  // own, keyed Figma name -> the Figma name that covers it.
  const aliases = manifest.aliases ?? {}
  const normalise = asset.normalise ?? ((name) => name)

  for (const platformName of platforms) {
    const platform = PLATFORMS[platformName]
    const spec = asset[platformName]
    const members = spec.members(readFileSync(join(repo, spec.enumPath), 'utf8'))
    const allowed = new Set([...knownUnmapped, ...Object.keys(aliases)].map(spec.keyFor))

    // Checked in BOTH directions on purpose. Only checking manifest -> enum
    // catches a deleted asset but stays silent on an added one, which is the
    // direction that actually happens: an asset lands in code with no mapping.
    const missingFromEnum = []
    const mapped = new Set()
    for (const name of Object.keys(items)) {
      const member = members.get(spec.keyFor(normalise(name)))
      if (!member) missingFromEnum.push(name)
      else mapped.add(member)
    }
    const missingFromManifest = [...members.entries()]
      .filter(([key, member]) => !mapped.has(member) && !allowed.has(key))
      .map(([, member]) => member)

    if (missingFromEnum.length || missingFromManifest.length) {
      failed = true
      if (missingFromEnum.length) {
        console.error(`[${assetName}/${platformName}] ${missingFromEnum.length} Figma component(s) have no enum entry:`)
        for (const n of missingFromEnum) console.error(`  ${n}`)
        console.error(`  → run the svg-asset-converter to add them to ${spec.enumPath}`)
      }
      if (missingFromManifest.length) {
        console.error(`[${assetName}/${platformName}] ${missingFromManifest.length} enum entr(ies) have no mapping:`)
        for (const m of missingFromManifest) console.error(`  ${m}`)
        console.error(`  → refresh ${asset.manifest} from Figma, or add the Figma name to its knownUnmapped list`)
      }
      continue
    }

    const outDir = join(root, platform.dir, asset.outSub)
    rmSync(outDir, { recursive: true, force: true })
    mkdirSync(outDir, { recursive: true })

    for (const [name, nodeId] of Object.entries(items)) {
      const member = members.get(spec.keyFor(normalise(name)))
      const reference = spec.reference(member)
      // Emits a bare enum reference, not a view or composable call: every
      // consumer takes the enum. Parents needing a rendered asset wrap it.
      const body = `// url=${asset.urlToken}?node-id=${nodeId.replace(':', '-')}
// source=${spec.enumPath}
// component=${reference.split('.')[0]}
import figma from 'figma'

export default {
  example: figma.${platform.tag}\`${reference}\`,${
    spec.imports.length ? `\n  imports: [${spec.imports.map((i) => `'${i}'`).join(', ')}],` : ''
  }
  id: '${assetName.replace(/s$/, '')}-${name}',
  metadata: { nestable: true },
}
`
      writeFileSync(join(outDir, `${pascal(name)}.figma.ts`), body)
    }

    console.log(
      `[${assetName}/${platformName}] generated ${readdirSync(outDir).length} templates in ${platform.dir}/${asset.outSub}/`,
    )
  }
}

process.exit(failed ? 1 : 0)
